+package ledger
+
+import (
+	"errors"
+)
+
+type BalanceVerifier struct{}
+
+// VerifyJournalBalance verifies that debits equal credits in double-entry books.
+func (v *BalanceVerifier) VerifyJournalBalance(entries []JournalEntry) error {
+	var totalDebits int64
+	var totalCredits int64
+
+	for _, entry := range entries {
+		if entry.Type == Debit {
+			totalDebits += entry.AmountCents
+		} else if entry.Type == Credit {
+			totalCredits += entry.AmountCents
+		}
+	}
+
+	if totalDebits != totalCredits {
+		return errors.New("double-entry ledger imbalance: debits do not equal credits")
+	}
+	return nil
+}
