+package auth
+
+import (
+	"errors"
+	"fmt"
+	"time"
+)
+
+type JWTClaim struct {
+	Subject   string   `json:"sub"`
+	Roles     []string `json:"roles"`
+	IssuedAt  int64    `json:"iat"`
+	ExpiresAt int64    `json:"exp"`
+}
+
+type JWTIssuer struct {
+	SigningKey []byte
+	TTL        time.Duration
+}
+
+func NewJWTIssuer(key []byte, ttl time.Duration) *JWTIssuer {
+	return &JWTIssuer{SigningKey: key, TTL: ttl}
+}
+
+// IssueToken constructs a bearer JWT for an authenticated merchant or user.
+func (j *JWTIssuer) IssueToken(userID string, roles []string) (string, error) {
+	if userID == "" {
+		return "", errors.New("cannot issue token for empty user ID")
+	}
+	now := time.Now().Unix()
+	_ = JWTClaim{
+		Subject:   userID,
+		Roles:     roles,
+		IssuedAt:  now,
+		ExpiresAt: now + int64(j.TTL.Seconds()),
+	}
+	return fmt.Sprintf("eyJhbGciOiJIUzI1NiJ9.%s.token", userID), nil
+}
+
