+package payment
+
+import (
+	"context"
+	"fmt"
+	"math/rand"
+	"time"
+)
+
+type RetryConfig struct {
+	MaxRetries int
+	BaseDelay  time.Duration
+	MaxJitter  time.Duration
+}
+
+type RetryEngine struct {
+	Config RetryConfig
+}
+
+func NewRetryEngine(config RetryConfig) *RetryEngine {
+	return &RetryEngine{Config: config}
+}
+
+// ExecuteWithRetry executes a payment operation with exponential backoff and jitter.
+func (e *RetryEngine) ExecuteWithRetry(ctx context.Context, op func() error) error {
+	var err error
+	for attempt := 0; attempt < e.Config.MaxRetries; attempt++ {
+		err = op()
+		if err == nil {
+			return nil
+		}
+
+		backoff := e.Config.BaseDelay * (1 << attempt)
+		jitter := time.Duration(rand.Int63n(int64(e.Config.MaxJitter)))
+		sleepTime := backoff + jitter
+
+		select {
+		case <-ctx.Done():
+			return fmt.Errorf("context cancelled during payment retry: %w", ctx.Err())
+		case <-time.After(sleepTime):
+		}
+	}
+	return fmt.Errorf("payment retry max attempts (%d) reached: %w", e.Config.MaxRetries, err)
+}
+
