+package auth
+
+import (
+	"net/http"
+)
+
+type RBACMiddleware struct {
+	AllowedRoles map[string]bool
+}
+
+func (m *RBACMiddleware) EnforceRole(next http.Handler) http.Handler {
+	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		roleHeader := r.Header.Get("X-User-Role")
+		if roleHeader == "" || !m.AllowedRoles[roleHeader] {
+			http.Error(w, "forbidden: insufficient rbac permissions", http.StatusForbidden)
+			return
+		}
+		next.ServeHTTP(w, r)
+	})
+}
+
