+package payment
+
+import (
+	"errors"
+	"fmt"
+)
+
+type PaymentStateMachine struct{}
+
+func (sm *PaymentStateMachine) Transition(intent *PaymentIntent, targetState string) error {
+	validTransitions := map[string][]string{
+		"PENDING":    {"PROCESSING", "FAILED"},
+		"PROCESSING": {"SUCCEEDED", "FAILED"},
+		"SUCCEEDED":  {},
+		"FAILED":     {"PROCESSING"}, // Allows retry transition
+	}
+
+	allowed, exists := validTransitions[intent.Status]
+	if !exists {
+		return fmt.Errorf("invalid current state: %s", intent.Status)
+	}
+
+	for _, state := range allowed {
+		if state == targetState {
+			return nil
+		}
+	}
+	return errors.New("unauthorized state transition from " + intent.Status + " to " + targetState)
+}
+
